</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++17 code you have to translate:
<original_code>
#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

using ll = long long;
using VI = vector<int>;

const ll MOD = 1000000007LL;
const ll MOD2 = 998244353LL;

VI pos[10];
int cnt = 0;
ll pw[15];
ll s[15];
ll cnt2, n;
int ans = 0;

int query(int fixpre, ll val) {
    ll res = 0;
    for (int d = 0; d < 7; ++d) {
        ll offset = (val - (ll)fixpre * pw[d]) % MOD2;
        if (offset < 0) offset += MOD2;
        int p = (int)(lower_bound(pos[d].begin(), pos[d].end(), MOD2 - offset) - pos[d].begin());
        res = (res + s[d] + offset * (ll)pos[d].size() - MOD2 * (ll)((int)pos[d].size() - p)) % MOD;
    }
    return (int)res;
}

void dfs(int val, int d) {
    int x = (int)((cnt - val + MOD2) % MOD2);
    pos[d].push_back(x);
    ++cnt;
    s[d] += x;
    if (d == 6) return;
    for (int i = 0; i < 10; ++i) dfs(val * 10 + i, d + 1);
}

void process_all() {
    vector<ll> st;
    st.push_back(0);

    while (!st.empty()) {
        ll val = st.back();
        st.pop_back();

        if (val * 1000000LL + 999999LL <= n && val * 10000000LL > n) {
            ans = (int)((ans + query(val, cnt2 + 1)) % MOD);
            cnt2 += cnt;
        } else {
            ++cnt2;
            ans = (int)((ans + ((cnt2 - val) % MOD2 + MOD2) % MOD2) % MOD);

            int start = (val == 0 ? 1 : 0);
            for (int i = 9; i >= start; --i) {
                ll child = val * 10 + i;
                if (child <= n) st.push_back(child);
            }
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    dfs(0, 0);
    for (int i = 0; i < 7; ++i) sort(pos[i].begin(), pos[i].end());
    pw[0] = 1;
    for (int i = 1; i < 13; ++i) pw[i] = pw[i - 1] * 10;

    cin >> n;
    cnt2 = -1;
    process_all();

    cout << ans << '\n';
    return 0;
}
</original_code>
